import { describe, it, expect } from 'vitest';
import {
  monthlyCashflow,
  savingsRate,
  burnRate,
  trailing12Expense,
} from './cashflow';
import type { Snapshot, TransactionDTO } from '../types';

const base: Omit<Snapshot, 'transactions'> = {
  budgetName: 'Test',
  currency: { code: 'EUR', symbol: '€', symbolFirst: true },
  accounts: [{ id: 'a', name: 'Check', offbudget: false, closed: false, balance: 0 }],
  categories: [
    { id: 'inc', name: 'Salary', group_id: 'g', is_income: true },
    { id: 'food', name: 'Food', group_id: 'g2', is_income: false },
  ],
  categoryGroups: [],
  payees: [{ id: 'pt', name: 'Transfer', transfer_acct: 'b' }],
  generatedAt: '2026-02-01T00:00:00Z',
};

let n = 0;
const tx = (p: Partial<TransactionDTO>): TransactionDTO => ({
  id: `t${n++}`,
  account: 'a',
  date: '2026-01-10',
  amount: 0,
  payee: null,
  category: null,
  transfer_id: null,
  is_parent: false,
  is_child: false,
  ...p,
});

const snap = (transactions: TransactionDTO[]): Snapshot => ({ ...base, transactions });

describe('cashflow', () => {
  it('computes monthly income, expense, net excluding transfers', () => {
    const s = snap([
      tx({ amount: 300000, category: 'inc' }),
      tx({ amount: -50000, category: 'food' }),
      tx({ amount: -99999, transfer_id: 't-x' }), // transfer leg, excluded
      tx({ amount: -77777, payee: 'pt' }), // transfer payee, excluded
    ]);
    const m = monthlyCashflow(s).find((x) => x.month === '2026-01')!;
    expect(m.income).toBe(300000);
    expect(m.expense).toBe(50000);
    expect(m.net).toBe(250000);
  });

  it('counts split children, not the parent', () => {
    const s = snap([
      tx({ id: 'p', amount: -10000, is_parent: true, category: null }),
      tx({ id: 'c1', amount: -6000, is_child: true, category: 'food' }),
      tx({ id: 'c2', amount: -4000, is_child: true, category: 'food' }),
    ]);
    const m = monthlyCashflow(s).find((x) => x.month === '2026-01')!;
    expect(m.expense).toBe(10000); // children only, parent skipped
  });

  it('treats uncategorised inflow as income', () => {
    const s = snap([tx({ amount: 12345, category: null })]);
    const m = monthlyCashflow(s).find((x) => x.month === '2026-01')!;
    expect(m.income).toBe(12345);
    expect(m.expense).toBe(0);
  });

  it('fills gap months between first and last transaction', () => {
    const s = snap([
      tx({ date: '2026-01-05', amount: -1000, category: 'food' }),
      tx({ date: '2026-03-05', amount: -2000, category: 'food' }),
    ]);
    const months = monthlyCashflow(s).map((m) => m.month);
    expect(months).toEqual(['2026-01', '2026-02', '2026-03']);
  });

  it('savings rate handles zero income', () => {
    expect(savingsRate([{ month: 'x', income: 1000, expense: 600, net: 400 }])).toBeCloseTo(0.4);
    expect(savingsRate([{ month: 'x', income: 0, expense: 100, net: -100 }])).toBe(0);
  });

  it('burn rate averages last window months', () => {
    const months = [
      { month: '1', income: 0, expense: 100, net: -100 },
      { month: '2', income: 0, expense: 300, net: -300 },
      { month: '3', income: 0, expense: 200, net: -200 },
    ];
    expect(burnRate(months, 2)).toBe(250);
  });

  it('trailing 12 month expense sums recent months', () => {
    // 13 distinct months: 2025-01 .. 2026-01, each -1000 spend.
    const clean: TransactionDTO[] = [];
    for (let i = 0; i < 13; i++) {
      const ym = `${2025 + Math.floor(i / 12)}-${String((i % 12) + 1).padStart(2, '0')}`;
      clean.push(tx({ date: `${ym}-10`, amount: -1000, category: 'food' }));
    }
    const s = snap(clean);
    // trailing 12 of 13 months => 12000
    expect(trailing12Expense(monthlyCashflow(s))).toBe(12000);
  });
});

import { describe, it, expect } from 'vitest';
import {
  fireNumber,
  fireProgress,
  leanFatTargets,
  projection,
  coastFireNumber,
  isCoasting,
  yearsToRetirement,
  runwayMonths,
  simulate,
} from './fire';

describe('fire', () => {
  it('fire number is spend / SWR', () => {
    expect(fireNumber(40000_00, 0.04)).toBe(1_000_000_00);
  });

  it('progress is netWorth / fireNumber', () => {
    expect(fireProgress(500_000_00, 40000_00, 0.04)).toBeCloseTo(0.5);
  });

  it('lean/base/fat targets scale with spend', () => {
    const t = leanFatTargets(40000_00, 0.04);
    expect(t.base).toBe(1_000_000_00);
    expect(t.lean).toBe(700_000_00);
    expect(t.fat).toBe(1_500_000_00);
  });

  it('projection reaches the fire number', () => {
    const s = projection({
      netWorth: 0,
      annualContribution: 50000_00,
      annualSpend: 40000_00,
      withdrawalRate: 0.04,
      realReturn: 0.05,
    });
    expect(s[0]).toEqual({ year: 0, netWorth: 0 });
    expect(s[s.length - 1].netWorth).toBeGreaterThanOrEqual(1_000_000_00);
  });

  it('coast fire number discounts the target by growth', () => {
    const coast = coastFireNumber(40000_00, 0.04, 0.05, 10);
    expect(coast).toBeLessThan(1_000_000_00);
    expect(coast).toBeGreaterThan(0);
    // Growing coast number for 10y at 5% should reach ~ fire number
    expect(coast * 1.05 ** 10).toBeCloseTo(1_000_000_00, -3);
  });

  it('isCoasting compares net worth to coast number', () => {
    expect(isCoasting(700_000_00, 40000_00, 0.04, 0.05, 10)).toBe(true);
    expect(isCoasting(100_000_00, 40000_00, 0.04, 0.05, 10)).toBe(false);
  });
});

describe('retirement', () => {
  it('returns 0 when already at target', () => {
    expect(
      yearsToRetirement({
        netWorth: 1_000_000_00,
        annualContribution: 0,
        annualSpend: 40000_00,
        withdrawalRate: 0.04,
        realReturn: 0.05,
      }),
    ).toBe(0);
  });

  it('returns a positive fractional number of years', () => {
    const y = yearsToRetirement({
      netWorth: 0,
      annualContribution: 50000_00,
      annualSpend: 40000_00,
      withdrawalRate: 0.04,
      realReturn: 0.05,
    });
    expect(y).not.toBeNull();
    expect(y!).toBeGreaterThan(10);
    expect(y!).toBeLessThan(20);
  });

  it('returns null when unreachable', () => {
    expect(
      yearsToRetirement({
        netWorth: 0,
        annualContribution: 0,
        annualSpend: 40000_00,
        withdrawalRate: 0.04,
        realReturn: 0.05,
      }),
    ).toBeNull();
  });
});

describe('runway', () => {
  it('months of expenses the assets cover', () => {
    expect(runwayMonths(60000, 20000)).toBe(3);
    expect(runwayMonths(100000, 20000)).toBe(5);
  });

  it('infinite runway when no spend', () => {
    expect(runwayMonths(1, 0)).toBe(Infinity);
  });
});

describe('whatif', () => {
  it('changing withdrawal rate changes the fire number', () => {
    const a = simulate({
      netWorth: 0,
      annualContribution: 50000_00,
      annualSpend: 40000_00,
      withdrawalRate: 0.04,
      realReturn: 0.05,
    });
    const b = simulate({
      netWorth: 0,
      annualContribution: 50000_00,
      annualSpend: 40000_00,
      withdrawalRate: 0.03,
      realReturn: 0.05,
    });
    expect(b.fireNumber).toBeGreaterThan(a.fireNumber);
  });
});

